# Date: 2026-07-09
# Version: 0.2.8-dev.003
# Function: Convert compact RPF density JSONL to legacy codon-level TXT table.
# Input: Compact RPF density JSONL generated by rpf_Density.
# Output: Legacy RPF density TXT table.

"""Command-line converter from compact RPF density JSONL to legacy TXT."""

from __future__ import annotations

import argparse

from utils.ribo import Ribo
from utils.ribo.ArgsParser import args_print, file_check, now_time


def json_to_txt_args_parser():
    parser = argparse.ArgumentParser(
        description="Convert compact RPF density JSONL to the legacy codon-level TXT table."
    )

    input_group = parser.add_argument_group("Required arguments")
    input_group.add_argument(
        "-i",
        dest="json_file",
        required=True,
        type=str,
        help="Input compact RPF density JSONL file. Gzip-compressed .gz files are supported.",
    )
    input_group.add_argument(
        "-o",
        dest="output_txt",
        required=True,
        type=str,
        help="Output legacy TXT file.",
    )

    args = parser.parse_args()
    file_check(args.json_file)
    args_print(args)
    return args


def main():
    now_time()
    print("\nConvert compact RPF density JSONL to legacy TXT.", flush=True)
    print("\nStep1: Checking the input arguments.", flush=True)
    args = json_to_txt_args_parser()

    print("\nStep2: Convert JSONL to TXT.", flush=True)
    Ribo.Ribo.json_to_txt(
        json_file=args.json_file,
        output_txt=args.output_txt,
    )

    print("\nAll done.", flush=True)
    now_time()


if __name__ == "__main__":
    main()
